import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.CCCdsIgc.js";const _=JSON.parse('{"title":"回归评测","description":"","frontmatter":{},"headers":[],"relativePath":"admin/evals.md","filePath":"admin/evals.md"}'),o={name:"admin/evals.md"};function s(l,t,i,n,c,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="回归评测" tabindex="-1">回归评测 <a class="header-anchor" href="#回归评测" aria-label="Permalink to &quot;回归评测&quot;">​</a></h1><p>改了专家的说明、技能、模型或提示词之后，以前答得好的问题现在还答得好吗？<strong>回归评测</strong>把一组固定的问题存下来，每次改完跑一遍、自动打分、和上一次对比，变差的题会标出来。</p><h2 id="建题集" tabindex="-1">建题集 <a class="header-anchor" href="#建题集" aria-label="Permalink to &quot;建题集&quot;">​</a></h2><p>后台「<strong>运维 → 回归评测</strong>」，新建题集：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>谁来回答</td><td>选一位专家，或者「普通办事助手」</td></tr><tr><td>执行机</td><td>一台常开的专用电脑（可以和<a href="./unattended.html">无人值守任务</a>用同一台），要用到的连接器、技能装好登录好；选了专家的话，这位专家要下发到这台电脑</td></tr><tr><td>权限上限</td><td>仅可查看 / 工作区内修改。评测一律<strong>只预演</strong>，不会真的改任何东西</td></tr><tr><td>及格分</td><td>有评分标准的题，模型打分不低于这个才算通过（默认 60）</td></tr></tbody></table><p>每道题写一个问题（像员工平时那样问），再至少填一种判分方式：</p><table tabindex="0"><thead><tr><th>判分方式</th><th>例子</th></tr></thead><tbody><tr><td>回答必须包含</td><td><code>12480</code>（一车间上周的真实产量）</td></tr><tr><td>回答不能包含</td><td><code>不知道</code>、<code>无法查询</code></td></tr><tr><td>正则</td><td><code>|\\s*车间\\s*|</code>（回答里要有车间表格）</td></tr><tr><td>评分标准</td><td>「要提到产量、达成率、不良率三项，不能编造数字」——由模型按这句话打 0-100 分</td></tr></tbody></table><h2 id="跑一次、看结果" tabindex="-1">跑一次、看结果 <a class="header-anchor" href="#跑一次、看结果" aria-label="Permalink to &quot;跑一次、看结果&quot;">​</a></h2><p>点「<strong>跑一次</strong>」，可以写一句这次改了什么（比如「专家说明改到 v3」）。题目派到执行机上，做完自动打分，页面上能看到：</p><ul><li>通过几题、平均几分；</li><li><strong>比上次退步</strong>的题（上次通过、这次没过）标成红色；</li><li>每题的检查结果、模型打分和理由、AI 的回答。</li></ul><p>同一个题集上一次还没跑完时不能再跑。执行机一直没上线，题目过期后算没通过。</p><div class="tip custom-block"><p class="custom-block-title">题目编号</p><p>和上一次对比是按题目编号对的。编号可以自己填（比如 <code>yield-weekly</code>）；改了编号，这一题就和以前的记录对不上了。</p></div><div class="info custom-block"><p class="custom-block-title">不会影响员工</p><p>评测只预演，需要确认的操作一律拒绝；评测对话不会写进 AI 的长期记忆，结果只在后台看。</p></div>',13)])])}const b=d(o,[["render",s]]);export{_ as __pageData,b as default};
